let bookScope='global';
function entryScope(e){return e.scope||(e.roleId||e.groupId?'local':'global')}
function renderBook(){const items=worldbook.filter(e=>entryScope(e)===bookScope);screen.innerHTML=`<section class="view">${title('世界书','THE STORIES BEHIND YOUR WORLD','<button class="round" id="newEntry" aria-label="新建世界书条目">+</button>')}<div class="notice">世界书是一份背景设定清单，让 AI 知道世界规则、人物身世和关系。全局供所有角色使用；局部只供指定角色或群聊使用。它不会自动记录聊天，聊天记忆由记忆花园整理。</div><div class="book-scope-tabs"><button id="globalBooks" class="${bookScope==='global'?'selected':''}">全局世界书 · ${worldbook.filter(e=>entryScope(e)==='global').length}</button><button id="localBooks" class="${bookScope==='local'?'selected':''}">局部世界书 · ${worldbook.filter(e=>entryScope(e)==='local').length}</button></div><button class="secondary full" id="bookRelations">人物关系 · 登记原本认识的角色</button><div class="book-summary">当前 ${items.filter(e=>e.enabled).length} 个启用条目 · ${items.length} 个条目</div><div id="entries"></div><details class="worldbook-help"><summary>怎样写世界书？</summary><p>全局示例：这个世界是玫瑰王国，货币是金币，大家生活在王都。</p><p>局部角色示例：月光先生是一位喜欢红茶的乐师，只交给月光先生。</p><p>局部群聊示例：这个群是花园茶会，只在这个群里生效。</p><p>常驻：每次请求都带入。关键词触发：最近六条消息出现关键词时带入，减少每次发送的内容。条目内容会发送到你配置的 API。</p></details><button class="secondary full" id="backBook">返回桌面</button></section>`;$('#globalBooks').onclick=()=>{bookScope='global';renderBook()};$('#localBooks').onclick=()=>{bookScope='local';renderBook()};$('#newEntry').onclick=()=>editEntry();$('#bookRelations').onclick=openRelationships;$('#backBook').onclick=()=>go('home');const list=$('#entries');if(!items.length)list.innerHTML='<div class="book-empty"><span>♧</span><p>这里还没有'+(bookScope==='global'?'全局':'局部')+'设定。</p><small>点右上角 ＋ 添加。</small></div>';items.forEach(e=>{const role=roles.find(r=>r.id===e.roleId),group=groups.find(g=>g.id===e.groupId),card=document.createElement('article');card.className='book-card';card.innerHTML=`<div class="book-card-top"><strong>${escapeHtml(e.name)}</strong><label class="switch-label"><input type="checkbox" ${e.enabled?'checked':''} aria-label="启用 ${escapeHtml(e.name)}">启用</label></div><div class="book-tags"><span>${e.mode==='always'?'常驻':'关键词触发'}</span><span>${entryScope(e)==='global'?'全局 · 全部角色':escapeHtml(e.groupId?'局部群聊 · '+(group?.name||'群聊已不存在'):'局部角色 · '+(role?.name||'角色已不存在'))}</span></div><p>${escapeHtml(e.content)}</p><button class="text-button">编辑条目 ↗</button>`;card.querySelector('input').onchange=ev=>{const before=e.enabled;e.enabled=ev.target.checked;try{saveBook();renderBook()}catch{e.enabled=before;toast('保存失败，请检查存储空间')}};card.querySelector('button').onclick=()=>editEntry(e.id);list.append(card)})}
function editEntry(id=null){bookEditing=id;const e=worldbook.find(e=>e.id===id),scope=e?entryScope(e):bookScope,target=e?.groupId?'group:'+e.groupId:e?.roleId?'role:'+e.roleId:current?.startsWith('group:')?'group:'+current:'role:'+(current||roles[0]?.id||''),d=$('#bookEditor');d.innerHTML=`<form id="bookForm"><div class="eyebrow">WORLDBOOK ENTRY</div><h2>${e?'编辑':'新建'}世界书条目</h2><label>条目名称<input name="entryName" required maxlength="60" value="${escapeHtml(e?.name||'')}" placeholder="例如：玫瑰王国"></label><label>世界书类型<select name="scope"><option value="global" ${scope==='global'?'selected':''}>全局 · 全部角色</option><option value="local" ${scope==='local'?'selected':''}>局部 · 指定角色或群聊</option></select></label><label id="localTargetLabel">局部生效对象<select name="localTarget"><optgroup label="角色">${roles.map(r=>`<option value="role:${r.id}" ${target==='role:'+r.id?'selected':''}>角色 · ${escapeHtml(r.name)}</option>`).join('')}</optgroup><optgroup label="群聊">${groups.map(g=>`<option value="group:${g.id}" ${target==='group:'+g.id?'selected':''}>群聊 · ${escapeHtml(g.name)}</option>`).join('')}</optgroup></select></label><label>触发方式<select name="mode"><option value="always" ${e?.mode==='always'?'selected':''}>常驻 · 每次聊天带入</option><option value="keywords" ${e?.mode==='keywords'?'selected':''}>关键词触发</option></select></label><label id="keywordsLabel">关键词 · 逗号或换行分隔<textarea name="keys" rows="2" maxlength="500" placeholder="王都，宫殿">${escapeHtml(e?.keys||'')}</textarea></label><label>背景内容<textarea name="content" required rows="5" maxlength="8000" placeholder="写下世界观、人物背景、关系或规则…">${escapeHtml(e?.content||'')}</textarea></label><label class="check"><input type="checkbox" name="enabled" ${e?.enabled!==false?'checked':''}>启用此条目</label><div class="actions"><button type="button" class="secondary" id="cancelEntry">取消</button><button class="primary">保存条目</button></div>${e?'<button type="button" class="text-button danger" id="deleteEntry">删除这个条目</button>':''}</form>`;const f=$('#bookForm'),change=()=>{$('#localTargetLabel').hidden=f.scope.value==='global';f.localTarget.required=f.scope.value==='local';$('#keywordsLabel').hidden=f.mode.value!=='keywords';f.keys.required=f.mode.value==='keywords'};f.scope.onchange=change;f.mode.onchange=change;change();$('#cancelEntry').onclick=()=>d.close();f.onsubmit=ev=>{ev.preventDefault();const local=f.scope.value==='local',value=f.localTarget.value,entry={id:id||crypto.randomUUID(),name:f.entryName.value.trim(),scope:f.scope.value,roleId:local&&value.startsWith('role:')?value.slice(5):'',groupId:local&&value.startsWith('group:')?value.slice(6):'',mode:f.mode.value,keys:f.keys.value.trim(),content:f.content.value.trim(),enabled:f.enabled.checked};if(!entry.name||!entry.content||local&&!entry.roleId&&!entry.groupId||entry.mode==='keywords'&&!entry.keys.split(/[,，;；\n]/).some(x=>x.trim())){toast('请填写名称、背景和有效的局部对象或关键词');return}const old=worldbook;worldbook=id?worldbook.map(x=>x.id===id?entry:x):[...worldbook,entry];try{saveBook();bookScope=entry.scope;d.close();renderBook();toast('世界书已保存')}catch{worldbook=old;toast('保存失败，请检查存储空间')}};if(e)$('#deleteEntry').onclick=()=>{const old=worldbook;worldbook=worldbook.filter(x=>x.id!==id);try{saveBook();d.close();renderBook();toast('条目已删除')}catch{worldbook=old;toast('删除失败，请检查存储空间')}};d.showModal()}
